package lk.ac.sliit.ridelink.ride.infrastructure.security;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import org.springframework.http.*; import org.springframework.security.core.AuthenticationException; import org.springframework.security.web.AuthenticationEntryPoint; import org.springframework.stereotype.Component; import java.io.IOException; import java.time.Instant; import java.util.*;
@Component public class RestAuthenticationEntryPoint implements AuthenticationEntryPoint {private final ObjectMapper mapper;public RestAuthenticationEntryPoint(ObjectMapper mapper){this.mapper=mapper;}public void commence(HttpServletRequest req,HttpServletResponse res,AuthenticationException e)throws IOException{res.setStatus(401);res.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(res.getOutputStream(),Map.of("timestamp",Instant.now(),"status",401,"error","Unauthorized","message","Authentication is required or the token is invalid","path",req.getRequestURI(),"validationErrors",List.of()));}}
